"""Secure per-organization file storage helpers."""
import re
import uuid
from pathlib import Path

from ..config import get_settings

settings = get_settings()

_SAFE_NAME_RE = re.compile(r"[^A-Za-z0-9._-]+")


def storage_root() -> Path:
    root = Path(settings.STORAGE_DIR).resolve()
    root.mkdir(parents=True, exist_ok=True)
    return root


def org_dir(org_id: str, sub: str = "datasets") -> Path:
    # org_id is a UUID generated by us — still validated defensively.
    if not re.fullmatch(r"[0-9a-fA-F-]{36}", org_id):
        raise ValueError("Invalid organization identifier.")
    path = storage_root() / org_id / sub
    path.mkdir(parents=True, exist_ok=True)
    return path


def sanitize_filename(name: str) -> str:
    name = Path(name).name  # strip any path components
    name = _SAFE_NAME_RE.sub("_", name)
    return name[:200] or "upload"


def new_stored_path(org_id: str, original_filename: str, sub: str = "datasets", ext: str | None = None) -> Path:
    """Random UUID filename — the user-supplied name is never used on disk."""
    ext = ext if ext is not None else Path(original_filename).suffix.lower()
    return org_dir(org_id, sub) / f"{uuid.uuid4().hex}{ext}"


def resolve_within(path_str: str, org_id: str) -> Path:
    """Resolve a stored path and guarantee it lives inside this org's directory."""
    p = Path(path_str).resolve()
    base = storage_root() / org_id
    if base not in p.parents:
        raise PermissionError("Path escapes organization storage.")
    return p
